-- Independent pedagogical questions created after analyzing user-provided
-- Telegram Desktop Pedmahorat|Guli HTML archive. NOT original channel wording.
-- NO HISTORICAL AUTHENTICITY CLAIM. 24 questions; server source links to M14-M16.
-- Stage in draft PR only until explicit user production approval.
begin;
do $guli_v3$
declare r record; v_subject uuid; v_construct uuid; v_lesson uuid; v_qid uuid; v_oid uuid; i int;
begin
 select id into strict v_subject from public.subjects where code='informatika';
 for r in select * from jsonb_to_recordset($bank$[{"n":201,"construct":"KS.01","stem":"O‘qituvchi bir mavzu bo‘yicha natijani ‘o‘quvchilar mavzuni biladi’ deb yozdi. Baholashga yaroqlilik uchun qanday o‘zgartirish kerak?","options":["Dars rejasini bekor qilish","Kuzatiladigan amal va muvaffaqiyat mezonini aniq belgilash","Faqat mavzu nomini kattaroq yozish","Materialni faqat video bilan berish"],"answer":1,"explanation":"Aniq va o‘lchanadigan natija baholash dalilini oldindan belgilaydi.","cognitive":"qollash","difficulty":3},{"n":202,"construct":"KS.03","stem":"Matn muharriri mashg‘ulotida test natijalari o‘quvchilarning ko‘pchiligi jadval kiritishni bilmasligini ko‘rsatdi. Keyingi darsda eng asosli ish qaysi?","options":["Barcha o‘quvchiga darhol maksimal baho berish","Natijalarni hech kimga ko‘rsatmaslik","Mazkur ko‘nikmani qayta mashq qildirish va yangi qisqa diagnostika olish","Mavzuni hech qachon qayta ko‘rmaslik"],"answer":2,"explanation":"Formativ baholash dalili o‘qitish qarorini va qayta aloqa mazmunini o‘zgartiradi.","cognitive":"qollash","difficulty":3},{"n":203,"construct":"KS.05","stem":"Sinfdagi guruhli ishda bir o‘quvchining fikri doim masxara qilinmoqda. O‘qituvchining ustuvor vazifasi qaysi?","options":["Masxarani to‘xtatib, xavfsiz muloqot va ishtirok qoidalarini tiklash","Barcha guruh ishlarini butunlay taqiqlash","Masxara qilgan bolalarni hamma oldida kamsitish","Vaziyatni e’tiborsiz qoldirish"],"answer":0,"explanation":"Xavfsiz rivojlantiruvchi muhit kamsitishni oldini olish va teng ishtirokni ta’minlashni talab qiladi.","cognitive":"qollash","difficulty":3},{"n":204,"construct":"KS.07","stem":"O‘qituvchi ota-ona bilan uchrashuvda boshqa o‘quvchining bahosi va sog‘lig‘i haqidagi ma’lumotni aytib yubormaslik uchun qanday yo‘l tutadi?","options":["Barcha sinf haqidagi shaxsiy ma’lumotni oshkor qiladi","Boshqa o‘quvchilarning telefonlarini tarqatadi","Muhokamani tashlab chiqib ketadi","Suhbatni faqat tegishli bolaning rivojlanishi va zarur hamkorlik bilan cheklaydi"],"answer":3,"explanation":"Oila bilan hamkorlikda boshqa bolalarga oid shaxsiy ma’lumotlar sir saqlanishi kerak.","cognitive":"mulohaza","difficulty":4},{"n":205,"construct":"PM.GEN.01","stem":"Didaktika atamasi qaysi yo‘nalishning nazariy asoslarini o‘rganadi?","options":["Ta’lim va o‘qitish jarayonini","Faqat sinf jihozlarini","Faqat tashkiliy yozishmalarni","Faqat maktab binosini"],"answer":0,"explanation":"Didaktika pedagogikaning ta’lim nazariyasini o‘rganuvchi tarmog‘idir.","cognitive":"bilish","difficulty":2},{"n":206,"construct":"PM.GEN.01","stem":"O‘qituvchi tarbiya va o‘qitishni yagona jarayon deb ko‘radi. Bu qanday umumiy pedagogik qarashga mos?","options":["Ta’lim va tarbiya bir-biriga aloqador emas","Pedagogik jarayonda ta’lim hamda tarbiya o‘zaro uzviy bog‘langan","Tarbiya faqat maktabdan tashqarida ro‘y beradi","Bilim olgan shaxsning qadriyatlari rivojlanmaydi"],"answer":1,"explanation":"Ta’lim va tarbiya pedagogik jarayonning bog‘liq tomonlaridir.","cognitive":"bilish","difficulty":2},{"n":207,"construct":"PM.GEN.02","stem":"Yangi mavzuni tushuntirishda murakkablik bosqichma-bosqich oshirilmoqda. Bu qanday didaktik talabga ko‘proq mos?","options":["Tasodifiy tanlash","Faqat mukofotlash","Tizimlilik va izchillik","Faqat nazorat"],"answer":2,"explanation":"Mazmunni mantiqiy ketma-ketlikda tashkil qilish tizimlilik va izchillikka asoslanadi.","cognitive":"qollash","difficulty":3},{"n":208,"construct":"PM.GEN.02","stem":"Bir xil qoidani real dasturdagi misol bilan sinab ko‘rish o‘quvchi uchun nimani mustahkamlaydi?","options":["Faqat yodlash tezligini","Faoliyatni nazoratdan chiqarishni","Darsdan tashqari tanlovni","Nazariya bilan amaliyotning bog‘liqligini"],"answer":3,"explanation":"Bilimni konkret faoliyatda qo‘llash nazariya va amaliyot birligini namoyon etadi.","cognitive":"qollash","difficulty":3},{"n":209,"construct":"PM.GEN.04","stem":"Darsda yangi tushuncha berilgach, o‘quvchilar oldingi ko‘nikmalarni ham mashq qilib, yangi bilimni sinab ko‘rmoqda. Bu qanday dars tuzilishiga yaqin?","options":["Faqat ma’lumot berish darsi","Kombinatsiyalashgan dars","Faqat nazorat darsi","Faqat mustaqil maslahat"],"answer":1,"explanation":"Kombinatsiyalashgan dars bir nechta didaktik vazifani birlashtirishi mumkin.","cognitive":"qollash","difficulty":3},{"n":210,"construct":"PM.GEN.04","stem":"O‘qituvchi har bir mavzu qismidan so‘ng qisqa savol berib, keyingi bosqichga o‘tishdan oldin tushunishni tekshiradi. Bu yondashuv nimaga yordam beradi?","options":["Tushunmovchiliklarni erta aniqlash va faoliyatni moslashtirishga","Baholash dalilini umuman ishlatmaslikka","Faqat dars vaqtini behuda sarflashga","O‘quvchilar ishtirokini kamaytirishga"],"answer":0,"explanation":"Kichik bosqichli tekshiruv darsni tezkor qayta rejalash uchun dalil beradi.","cognitive":"qollash","difficulty":3},{"n":211,"construct":"PM.GEN.05","stem":"Sinf rahbari ota-onalar bilan hamkorlik rejasini tuzdi. Unda qaysi band eng asosiy pedagogik maqsadni aks ettiradi?","options":["Faqat hisobot hajmini oshirish","Boshqa o‘quvchilar haqidagi ma’lumotni tarqatish","Farzand rivoji bo‘yicha aniq vazifa, kelishuv va kuzatish mezonini belgilash","Barcha o‘quvchilarni bir xil baholashga majburlash"],"answer":2,"explanation":"Hamkorlik farzandning ta’lim-tarbiyaviy rivojlanishini qo‘llashga qaratilishi kerak.","cognitive":"qollash","difficulty":3},{"n":212,"construct":"PM.GEN.06","stem":"Muallim nutqidagi tovushlar ravshan, so‘zlar tushunarli talaffuz qilinyapti. Ushbu sifat qaysi tushunchaga eng yaqin?","options":["Pedagogik xayol","Shaxslararo arbitraj","Jismoniy tarbiya","Diksiya"],"answer":3,"explanation":"Diksiya tovush va bo‘g‘inlarning ravshan hamda aniq talaffuzini ifodalaydi.","cognitive":"bilish","difficulty":2},{"n":213,"construct":"PM.GEN.06","stem":"O‘qituvchi o‘quvchining noto‘g‘ri javobini sinf oldida masxara qilmay, muloyim savollar bilan xatosini topishga undaydi. Yetakchi tushuncha qaysi?","options":["Pedagogik takt","Pedagogik befarqlik","Faqat nazorat uchun jazolash","Tarixiy metod"],"answer":0,"explanation":"Pedagogik takt talabchanlikni o‘quvchi qadr-qimmatini saqlagan holda namoyon qiladi.","cognitive":"qollash","difficulty":3},{"n":214,"construct":"PM.GEN.06","stem":"Muallim darsdagi hissiyotini jilovlab, vaziyatga mos ohang, mimika va imo-ishoradan foydalandi. Bu nimaning amaliy belgisi?","options":["Sinov muddati","Pedagogik texnika","Faqat sinf jurnali","Laboratoriya tajribasi"],"answer":1,"explanation":"Pedagogik texnika o‘z-o‘zini boshqarish va nutq-imo-ishora vositalarini o‘rinli qo‘llashni o‘z ichiga oladi.","cognitive":"qollash","difficulty":3},{"n":215,"construct":"PM.GEN.07","stem":"O‘qituvchi mavzuni boshlashdan oldin o‘quvchilarning mumkin bo‘lgan xatolarini tasavvur qilib, muqobil tushuntirishlar tayyorladi. Qaysi qobiliyat namoyon?","options":["Faqat nutq balandligi","Faqat ma’muriy yozishma","Pedagogik xayol","Jismoniy harakat"],"answer":2,"explanation":"Pedagogik xayol kelajakdagi didaktik holatlarni oldindan tasavvur qilishga yordam beradi.","cognitive":"qollash","difficulty":3},{"n":216,"construct":"PM.GEN.07","stem":"O‘quvchining yuz ifodasi va javobidagi ikkilanishdan qiyinchilikni payqagan muallim qanday qobiliyatdan foydalandi?","options":["Akademik qobiliyat","Faqat nazorat qobiliyati","Tashkiliy hujjat yuritish","Perseptiv qobiliyat"],"answer":3,"explanation":"Perseptiv qobiliyat boshqa shaxs holatini nozik belgilar orqali idrok etishdir.","cognitive":"qollash","difficulty":3},{"n":217,"construct":"PM.GEN.07","stem":"Murakkab tushunchani qisqa o‘xshatish, rasm va sodda amaliy misol bilan anglatish ko‘proq qaysi qobiliyat?","options":["Didaktik qobiliyat","Faqat tashqi ko‘rinish","Faqat nazoratni o‘tkazish","Arxivlash ko‘nikmasi"],"answer":0,"explanation":"Didaktik qobiliyat bilimni o‘zlashtiriladigan shaklda bayon etishdir.","cognitive":"bilish","difficulty":2},{"n":218,"construct":"PM.GEN.08","stem":"Guruhlar masalani qismlarga bo‘lib o‘rganadi. Har bir ishtirokchi o‘z qismi bo‘yicha mutaxassis bo‘lib, keyin dastlabki guruhini o‘qitadi. Qaysi metod?","options":["Faqat yakka ma’ruza","Ajurli arra","Sinfni faqat kuzatish","Yozma diktant"],"answer":1,"explanation":"Ajurli arra metodida ekspert va asosiy guruhlar almashinuvi mavjud.","cognitive":"qollash","difficulty":3},{"n":219,"construct":"PM.GEN.08","stem":"Muammoli ta’limda o‘qituvchining asosiy roli qaysi?","options":["Barcha javobni oldindan aytib berish","O‘quvchi savollarini taqiqlash","Bilish ziddiyatini qo‘yib, izlanish va dalillashni yo‘naltirish","Faqat final bahoni e’lon qilish"],"answer":2,"explanation":"Muammoli ta’lim o‘quvchini asoslangan mustaqil yechimga olib keladigan bilish vaziyatini yaratadi.","cognitive":"qollash","difficulty":3},{"n":220,"construct":"PM.GEN.08","stem":"O‘quvchilar mavzuni o‘zlashtirish tezligi bilan farq qiladi. O‘qituvchi bitta maqsadni saqlab, ko‘mak va vazifalar murakkabligini farqladi. Qanday yondashuv?","options":["Faqat bo‘ysundirish","Yagona qat’iy usulni o‘zgartirmaslik","Yagona yozma diktant","Differensial yondashuv"],"answer":3,"explanation":"Differensial yondashuv yordam va vazifa darajasini ehtiyojga ko‘ra moslashtiradi.","cognitive":"qollash","difficulty":3},{"n":221,"construct":"PM.GEN.08","stem":"O‘quvchilar yakuniy loyiha mahsulotini yaratishdan avval muammoni o‘rganib, reja tuzishdi va rollarni taqsimlashdi. Bunda qaysi belgiga ko‘proq e’tibor qilinadi?","options":["Jarayon va natijani birga baholashga","Faqat oxirgi taqdimot bezagiga","Faqat darsning davomiyligiga","Faqat yakuniy testdagi bir harfga"],"answer":0,"explanation":"Loyiha ta’limida rejalash, hamkorlik, izlanish va mahsulotning sifati birga baholanadi.","cognitive":"mulohaza","difficulty":4},{"n":222,"construct":"PM.GEN.08","stem":"O‘quvchi o‘qigan formulani yangi vaziyatda mustaqil ishlatdi. Bloom taksonomiyasiga ko‘ra bu nimaga misol?","options":["Faqat eslab qolish","Qo‘llash","Faqat nomlash","Faqat nusxalash"],"answer":1,"explanation":"Bilim yoki ko‘nikmani yangi masalada ishlatish qo‘llash bosqichiga misol.","cognitive":"qollash","difficulty":3},{"n":223,"construct":"PM.MET.02","stem":"Informatika darsida o‘quvchilar uchta algoritmning chegaraviy qiymatlarda ishlashini test qilmoqda. O‘qituvchi natijadan qanday foydalanishi metodik jihatdan to‘g‘ri?","options":["Kodga qarab xatoni tushuntirmasdan past baho qo‘yish","Faqat eng tez algoritmni misolsiz tanlash","Test dalillari asosida algoritmni taqqoslash va to‘g‘ri xulosani asoslash","Barcha tekshiruvlarni to‘xtatish"],"answer":2,"explanation":"Chegaraviy testlar tahlili algoritmik fikrlash va asosli qarorni rivojlantiradi.","cognitive":"mulohaza","difficulty":4},{"n":224,"construct":"PM.MET.03","stem":"O‘quvchi dasturdagi xatoni ko‘rdi, ammo uning sababini bilmaydi. O‘qituvchi qaysi ko‘makni birinchi beradi?","options":["O‘quvchi o‘rniga barcha kodni qayta yozadi","Xatoni e’tiborsiz qoldirishni buyuradi","Barcha javoblarni ko‘chirishga ruxsat beradi","Xabar va minimal test orqali xatoni qayta kuzatish yo‘lini ko‘rsatadi"],"answer":3,"explanation":"Debugging o‘quvchining xatoni kuzatish va sinab ko‘rish ko‘nikmalarini mustahkamlaydi.","cognitive":"qollash","difficulty":3}]$bank$::jsonb)
 as t(n int,construct text,stem text,options jsonb,answer int,explanation text,cognitive text,difficulty int)
 loop
   select c.id,l.id into v_construct,v_lesson
     from public.constructs c
     join public.lesson_constructs lc on lc.construct_id=c.id
     join public.lessons l on l.id=lc.lesson_id
     where c.code=r.construct and c.is_active and l.status='published'::public.content_status
       and l.slug !~ '^m(14|15|16)-[0-9]+$'
     order by l.id limit 1;
   if v_construct is null or v_lesson is null then
     raise exception 'pedguli_html_original_source_lesson_missing: %',r.construct; end if;
   v_qid:=('79250000-0000-4000-8000-'||lpad(r.n::text,12,'0'))::uuid;
   insert into public.questions(id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,status,source_reference,source_lesson_id)
   values(v_qid,v_subject,v_construct,
     case when r.construct like 'KS.%' then 'KS' when r.construct like 'PM.GEN.%' then 'PM.GEN' else 'PM.MET' end,
     'Y1'::public.question_format,r.cognitive::public.cognitive_level,r.difficulty,r.stem,
     'published'::public.content_status,
     'authored:pedguli-html-concepts:v3:'||r.construct||':'||r.n,v_lesson)
   on conflict(id) do nothing;
   for i in 0..3 loop
     v_oid:=('79260000-0000-4000-8000-'||lpad((r.n*10+i)::text,12,'0'))::uuid;
     insert into public.question_options(id,question_id,side,order_idx,content_md)
     values(v_oid,v_qid,'a',i+1,r.options->>i) on conflict(id) do nothing;
   end loop;
   v_oid:=('79260000-0000-4000-8000-'||lpad((r.n*10+r.answer)::text,12,'0'))::uuid;
   insert into public.question_keys(question_id,payload,explanation_md)
   values(v_qid,jsonb_build_object('correct_option_id',v_oid),r.explanation)
   on conflict(question_id) do nothing;
 end loop;
end
$guli_v3$;
commit;